arguments.command:
ls -a; echo '---'; d=$(mktemp -d); cd "$d" && python3 -c "
import sys; sys.path.insert(0, '$OLDPWD' if False else '$(pwd)')
" ; cd - >/dev/null; echo '--- smoke test in temp dir ---'; PYTHONPATH=/workspace:/$(pwd) python3 - <<'EOF'
import os, tempfile, json, notes
d = tempfile.mkdtemp(); os.chdir(d)
print(notes.add_note("buy milk"), notes.add_note("call dentist"))
print(notes.list_notes())
print("deleted:", notes.delete_note(1))
print("file:", json.load(open("notes.json")))
try: notes.delete_note(5)
except notes.NoteNotFoundError as e: print("out of range ->", type(e).__name__, e)
try: notes.delete_note(0)
except notes.InvalidNoteNumber as e: print("bad number ->", type(e).__name__, e)
EOF
